 'H_chuchu_phonics':'hq3yfQnllfQ',
 'I_believer':'7wtfhZwyrcc',
 'J_allaboutbass':'7PCkvCPvDXk',
}

def get_player(vid):
    body=json.dumps({"context":{"client":{"clientName":"WEB","clientVersion":"2.20240702.01.00","hl":"en"}},"videoId":vid}).encode()
    req=urllib.request.Request("https://www.youtube.com/youtubei/v1/player",data=body,headers={**UA,'Content-Type':'application/json'})
    return json.loads(urllib.request.urlopen(req,timeout=40).read())

def storyboard_frames(vid):
    d=get_player(vid)
    sb=d['storyboards']
    spec=None
    for k,v in sb.items():
        if k.endswith('playerStoryboardSpecRenderer'): spec=v['spec']
    parts=spec.split('|')
    base=parts[0]
    levels=parts[1:]
    L=len(levels)-1
    f=levels[L].split('#')
    w,h,cols,rows=int(f[1]),int(f[2]),int(f[3]),int(f[4])
    total=int(f[5]) if len(f)>5 else 0
    if total==0: total=cols*rows*100  # fallback
    n_sheets=math.ceil(total/(cols*rows))
    frames=[]
    for n in range(n_sheets):
        url=base.replace('$L',str(L)).replace('$N','M%d'%n)
        fn=f"sb_{vid}_{n}.jpg"
        if not os.path.exists(fn):
            req=urllib.request.Request(url,headers=UA)
            open(fn,'wb').write(urllib.request.urlopen(req,timeout=40).read())
        im=Image.open(fn).convert('RGB')
        for r in range(rows):
            for c in range(cols):
                box=(c*w,r*w and 0 or 0,0,0)  # placeholder
        # slice properly
        for r in range(rows):
            for c in range(cols):
                x0,y0=c*w,r*h
                if x0+w<=im.size[0] and y0+h<=im.size[1]:
                    t=im.crop((x0,y0,x0+w,y0+h))
                    t=t.resize((16,9))
                    frames.append(list(t.getdata()))
    return frames

def seq_to_segments(frames,N=100):
    nf=len(frames)
    segs=[]
    for s in range(N):
        a,b=int(s*nf/N),max(int((s+1)*nf/N),int(s*nf/N)+1)
        rs=gs=bs=cnt=0
        for fr in frames[a:b]:
            for (r,g,b_) in fr[::7]:
                rs+=r;gs+=g;bs+=b_;cnt+=1
        segs.append((rs/cnt,gs/cnt,bs/cnt))
    return segs

# barcode segments
im=Image.open('barcode.png').convert('RGB'); px=im.load(); W,H=im.size
bar=[]
for i in range(100):
    rs=gs=bs=n=0
    for x in range(i*10,(i+1)*10):
        for y in range(0,H,4):
            r,g,b=px[x,y];rs+=r;gs+=g;bs+=b;n+=1
    bar.append((rs/n,gs/n,bs/n))

def dist(seg):
    return sum((a[0]-b[0])**2+(a[1]-b[1])**2+(a[2]-b[2])**2 for a,b in zip(bar,seg))**0.5

results={}
